  "candidate_motifs": [
    {
      "id": "motif:1",
      "label": "Partition of a kingdom among sons leading to jealous rebellion and contest over royal legitimacy",
      "taxonomy_refs": [
        "royal_legitimacy",
        "sibling_pair"
      ],
      "basis": "Feridn divides his empire among his three sons, giving different lands to Slim, Tr, and Irij. The more attractive kingdom of Persia goes to Irij, while Slim and Tr receive harsher regions. Slim and Tr resent the distribution, complain that Irij has the best kingdom, and send a messenger demanding that Irij be given a more humble portion, threatening to raise armies to overthrow him and ruin Persia if their demands are not met.",
      "evidence_refs": [
        "ev:2",
        "ev:3",
        "ev:4"
      ],
      "confidence": "medium",
      "cautions": "The passage focuses on a triad of brothers rather than a single sibling pair, and while royal legitimacy is central, details beyond this excerpt may further shape the motif."
    },
    {
      "id": "motif:2",
      "label": "Aged king offering wisdom about the fleeting nature of worldly power and counseling peace",
      "taxonomy_refs": [
        "wisdom"
      ],
      "basis": "Feridn, described as old and near the end of his life, tells his sons that he has given them kingdoms and done them no wrong, reminds them to fear God, reflects that worldly possessions will soon pass from him, and urges them with paternal love to be content with their lot, avoid rebellion, and cherish peace instead of unnatural strife.",
      "evidence_refs": [
        "ev:5",
        "ev:6"
      ],
      "confidence": "high",
      "cautions": "The motif is limited to ethical and philosophical counsel within this political conflict, without explicit supernatural framing."
    },
    {
      "id": "motif:3",
      "label": "Younger prince renouncing his throne and life’s glory as a sacrifice to prevent fraternal bloodshed",
      "taxonomy_refs": [
        "sacrifice",
        "royal_legitimacy",
        "wisdom"
      ],
      "basis": "Irij, the youngest son and ruler of Persia, is threatened by his elder brothers' alliance. At his father's urging, he acknowledges that he cannot resist their forces and declares he will willingly sacrifice his throne and diadem rather than fight his brothers. He reflects on how quickly man passes away and on the illusory nature of worldly glory, then decides to go to his brothers and place his kingdom at their disposal to seek peace.",
      "evidence_refs": [
        "ev:6",
        "ev:7"
      ],
      "confidence": "high",
      "cautions": "The passage shows Irij’s intention to sacrifice power to prevent conflict; the eventual outcome and broader narrative context are not included here."
    },
    {
      "id": "motif:4",
      "label": "Philosophical meditation on mortality and the vanity of worldly glory",
      "taxonomy_refs": [
        "wisdom"
      ],
      "basis": "Irij speaks of the Heavens and how quickly man is gone, likening life to a breath of wind, and questions whether such a world should be deplored, calling glory an illusion and a cheat, and recalling how it failed even Jemshd, who once had the world at his feet.",
      "evidence_refs": [
        "ev:7"
      ],
      "confidence": "high",
      "cautions": "The meditation is framed by a specific political and familial crisis, and may be part of a larger didactic pattern in the surrounding text."
    }
