      "id": "obs:1",
      "text": "After Sm’s departure and return to Karugsr and Mzindern, Zl goes with Rustem to Sistan, a province under his governance, and settles Rustem there.",
      "category": "action",
      "evidence_refs": ["ev:1"]
    },
