      "id": "obs:22",
      "text": "After the destruction, Rustem returns to Zabulistan, where Zl embraces him and bestows public honors; Rustem’s mother kisses and embraces him, and everyone joins in blessing him.",
      "category": "sequence",
      "evidence_refs": ["ev:7"]
    }
